<?php

namespace App\Http\Controllers;

use App\Domain\Administration\AdminAudit;
use App\Domain\Administration\Modules;
use App\Domain\Administration\NumberSequence;
use App\Domain\Finance\FinanceService;
use App\Models\Organization;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class FinanceController extends Controller
{
    private function enabled():void{abort_unless(app(Modules::class)->enabled('finance'),404);}
    private function canDo(Request $r,string $p):bool{return $r->user()->isSuperAdmin()||$r->user()->can($p);}
    private function org(Request $r):Organization{$id=(int)($r->input('organization_id')?:$r->query('organization_id')?:$r->user()->active_organization_id?:$r->user()->organizations()->orderBy('organizations.name')->value('organizations.id'));abort_unless($id&&$r->user()->canAccessOrganization($id),403);$org=Organization::findOrFail($id);abort_unless($org->is_active||$r->user()->isSuperAdmin(),403);return $org;}

    public function index(Request $request)
    {
        return $this->showSection($request, 'overview');
    }

    public function invoices(Request $request) { return $this->showSection($request, 'invoices'); }
    public function payments(Request $request) { return $this->showSection($request, 'payments'); }
    public function credits(Request $request) { return $this->showSection($request, 'credits'); }
    public function expenses(Request $request) { return $this->showSection($request, 'expenses'); }
    public function budgets(Request $request) { return $this->showSection($request, 'budgets'); }
    public function taxCodes(Request $request) { return $this->showSection($request, 'tax-codes'); }
    public function recurring(Request $request) { return $this->showSection($request, 'recurring'); }
    public function limits(Request $request) { return $this->showSection($request, 'limits'); }
    public function reports(Request $request) { return $this->showSection($request, 'reports'); }
    public function revenue(Request $request) { return $this->showSection($request, 'revenue'); }
    public function receivables(Request $request) { return $this->showSection($request, 'receivables'); }

    private function showSection(Request $request, string $section)
    {
        $this->enabled();
        $permission = match ($section) {
            'invoices' => 'finance.invoices.manage', 'payments' => 'finance.payments.manage',
            'credits' => 'finance.credits.manage', 'expenses' => 'finance.expenses.manage',
            'budgets' => 'finance.budgets.manage', 'tax-codes' => 'finance.taxes.manage',
            'recurring' => 'finance.recurring.manage', 'limits' => 'finance.limits.manage',
            'reports', 'revenue', 'receivables' => 'finance.reports.view', default => 'finance.view',
        };
        $overviewAccess = $section === 'overview' && (
            $this->canDo($request, 'finance.invoices.manage') || $this->canDo($request, 'finance.expenses.manage') ||
            $this->canDo($request, 'finance.payments.manage') || $this->canDo($request, 'finance.credits.manage') ||
            $this->canDo($request, 'finance.reports.view')
        );
        abort_unless($this->canDo($request, 'finance.view') || $this->canDo($request, $permission) || $overviewAccess, 403);
        $org=$this->org($request);
        $invoices=DB::table('finance_invoices')->where('organization_id',$org->id)->orderByDesc('invoice_date')->orderByDesc('id')->limit(150)->get();
        foreach($invoices as $invoice){$invoice->paid=(float)DB::table('finance_payment_allocations as a')->join('finance_payments as p','p.id','=','a.payment_id')->where('a.invoice_id',$invoice->id)->where('p.status','posted')->sum('a.amount');$invoice->credited=(float)DB::table('finance_credit_notes')->where('invoice_id',$invoice->id)->where('status','issued')->sum('total');$invoice->outstanding=max(0,(float)$invoice->total-$invoice->paid-$invoice->credited);$invoice->latest_approval=DB::table('finance_invoice_approvals')->where('invoice_id',$invoice->id)->orderByDesc('id')->first();}
        $payments=DB::table('finance_payments')->where('organization_id',$org->id)->orderByDesc('paid_on')->limit(60)->get();
        $expenses=DB::table('finance_expenses as e')->join('users as u','u.id','=','e.claimant_id')->where('e.organization_id',$org->id)->where(function($q)use($request){if(!$this->canDo($request,'finance.expenses.approve')&&!$this->canDo($request,'finance.expenses.manage'))$q->where('e.claimant_id',$request->user()->id); })->select('e.*','u.name as claimant_name')->orderByDesc('e.spent_on')->limit(80)->get();
        $credits=DB::table('finance_credit_notes as c')->join('finance_invoices as i','i.id','=','c.invoice_id')->where('c.organization_id',$org->id)->select('c.*','i.reference as invoice_reference')->orderByDesc('c.created_at')->limit(60)->get();
        $taxCodes=DB::table('finance_tax_codes')->where('organization_id',$org->id)->orderBy('code')->get();$budgets=DB::table('finance_budgets')->where('organization_id',$org->id)->where('status','active')->orderBy('starts_on')->get();
        foreach($budgets as $budget){$q=DB::table('finance_invoices')->where('organization_id',$org->id)->where('currency',$budget->currency)->whereIn('status',['issued','part_paid','paid','overdue'])->whereBetween('invoice_date',[$budget->starts_on,$budget->ends_on]);if($budget->department_name)$q->where('department_name',$budget->department_name);if($budget->service_name)$q->where('service_name',$budget->service_name);$budget->actual=(float)$q->sum('total');$budget->variance=(float)$budget->amount-$budget->actual;}
        $recurring=DB::table('finance_recurring_schedules')->where('organization_id',$org->id)->orderBy('next_invoice_on')->get();$limits=DB::table('finance_approval_limits')->where('organization_id',$org->id)->orderBy('role_name')->get();
        $receivables=[];$receivablesByCurrency=[];$overdueCount=0;
        $open=DB::table('finance_invoices')->where('organization_id',$org->id)->whereIn('status',['issued','part_paid','overdue'])->get();
        foreach($open as $invoice){
            $paid=(float)DB::table('finance_payment_allocations as a')->join('finance_payments as p','p.id','=','a.payment_id')->where('a.invoice_id',$invoice->id)->where('p.status','posted')->sum('a.amount');
            $credits=(float)DB::table('finance_credit_notes')->where('invoice_id',$invoice->id)->where('status','issued')->sum('total');$balance=max(0,(float)$invoice->total-$paid-$credits);
            $dueDate = \Illuminate\Support\Carbon::parse($invoice->due_date)->startOfDay();
            $daysOverdue = $dueDate->lt(today()->startOfDay()) ? (int) $dueDate->diffInDays(today()->startOfDay()) : 0;
            if($daysOverdue > 0)$overdueCount++;
            $receivables[] = (object) ['reference' => $invoice->reference, 'customer_name' => $invoice->customer_name, 'currency' => $invoice->currency, 'invoice_date' => $invoice->invoice_date, 'due_date' => $invoice->due_date, 'total' => (float) $invoice->total, 'balance' => $balance, 'days_overdue' => $daysOverdue, 'status' => $invoice->status];
            $receivablesByCurrency[$invoice->currency] ??= ['total'=>0,'current'=>0,'days_1_30'=>0,'days_31_60'=>0,'days_61_90'=>0,'days_90_plus'=>0];
            $bucket=$daysOverdue===0?'current':($daysOverdue<=30?'days_1_30':($daysOverdue<=60?'days_31_60':($daysOverdue<=90?'days_61_90':'days_90_plus')));
            $receivablesByCurrency[$invoice->currency]['total'] += $balance;
            $receivablesByCurrency[$invoice->currency][$bucket] += $balance;
        }
        if (!$receivablesByCurrency) $receivablesByCurrency = ['GHS'=>['total'=>0,'current'=>0,'days_1_30'=>0,'days_31_60'=>0,'days_61_90'=>0,'days_90_plus'=>0]];
        $invoiceTotals=DB::table('finance_invoices')->where('organization_id',$org->id)->whereIn('status',['issued','part_paid','paid','overdue'])->selectRaw('currency, sum(total) as amount')->groupBy('currency')->orderBy('currency')->get();
        $collectionTotals=DB::table('finance_payments')->where('organization_id',$org->id)->where('status','posted')->selectRaw('currency, sum(amount) as amount')->groupBy('currency')->orderBy('currency')->get();
        $currency=$invoices->first()->currency??'GHS';$metrics=['expenses_pending'=>DB::table('finance_expenses')->where('organization_id',$org->id)->where('status','pending_approval')->count(),'overdue_invoices'=>$overdueCount];
        $revenue=DB::table('finance_invoices')->where('organization_id',$org->id)->whereIn('status',['issued','part_paid','paid','overdue'])->whereBetween('invoice_date',[today()->startOfYear()->toDateString(),today()->endOfYear()->toDateString()])->selectRaw("customer_name, coalesce(service_name, 'Unspecified') as service_name, coalesce(department_name, 'Unallocated') as department_name, currency, sum(total) as total, sum(tax_total) as tax_total")->groupBy('customer_name','service_name','department_name','currency')->orderByDesc('total')->limit(100)->get();
        $sectionMetaBySection = [
            'overview' => ['Finance overview', 'Revenue, receivables and current finance activity.'],
            'invoices' => ['Invoices', 'Create, approve, issue and track customer invoices.'],
            'payments' => ['Record payment', 'Record customer receipts and reconcile them to statements.'],
            'credits' => ['Credit notes', 'Submit credit notes and review approval status.'],
            'expenses' => ['Expense claims', 'Review employee claims and record reimbursements.'],
            'budgets' => ['Budgets & variance', 'Compare approved budgets with invoiced activity.'],
            'tax-codes' => ['Tax codes', 'Manage tax rates used on invoice lines.'],
            'recurring' => ['Recurring invoices', 'Manage schedules that create invoice drafts.'],
            'limits' => ['Approval limits', 'Set currency limits for invoice approvers.'],
            'reports' => ['Revenue & reports', 'Review receivables, collections and revenue by client.'],
            'revenue' => ['Revenue', 'Review billed revenue by client, service and department for the current year.'],
            'receivables' => ['Receivables', 'Review open customer balances and aging by due date.'],
        ];
        $sectionMeta = $sectionMetaBySection[$section] ?? $sectionMetaBySection['overview'];
        $sectionSummary = match ($section) {
            'invoices' => [['Invoices', $invoices->count()], ['Awaiting approval', $invoices->where('status', 'pending_approval')->count()], ['Issued / open', $invoices->whereIn('status', ['issued','part_paid','overdue'])->count()], ['Overdue', $metrics['overdue_invoices']]],
            'payments' => [['Payments', $payments->count()], ['Unreconciled', $payments->where('is_reconciled', false)->count()], ['Collected', $collectionTotals->map(fn ($row) => $row->currency.' '.number_format($row->amount, 2))->join(' · ') ?: '—']],
            'credits' => [['Credit notes', $credits->count()], ['Awaiting approval', $credits->where('status','pending_approval')->count()], ['Issued', $credits->where('status','issued')->count()]],
            'expenses' => [['Claims', $expenses->count()], ['Awaiting review', $expenses->where('status','pending_approval')->count()], ['Approved', $expenses->where('status','approved')->count()], ['Reimbursed', $expenses->where('status','reimbursed')->count()]],
            'budgets' => [['Active budgets', $budgets->count()], ['Over budget', $budgets->where('variance', '<', 0)->count()], ['Within budget', $budgets->where('variance', '>=', 0)->count()]],
            'tax-codes' => [['Tax codes', $taxCodes->count()], ['Active', $taxCodes->where('is_active', true)->count()]],
            'recurring' => [['Schedules', $recurring->count()], ['Active', $recurring->where('is_active', true)->count()], ['Due', $recurring->where('next_invoice_on', '<=', today()->toDateString())->where('is_active', true)->count()]],
            'limits' => [['Configured limits', $limits->count()], ['Pending approvals', $invoices->where('status','pending_approval')->count()]],
            'reports' => [['Open receivables', collect($receivablesByCurrency)->map(fn ($row, $ccy) => $ccy.' '.number_format($row['total'], 2))->join(' · ')], ['Overdue invoices', $metrics['overdue_invoices']], ['Revenue rows', $revenue->count()]],
            'revenue' => [['Revenue groups', $revenue->count()], ['Billed invoices', $invoices->whereIn('status', ['issued','part_paid','paid','overdue'])->count()], ['Current-year basis', today()->year]],
            'receivables' => [['Open invoices', count($receivables)], ['Overdue invoices', $metrics['overdue_invoices']], ['Outstanding', collect($receivablesByCurrency)->map(fn ($row, $ccy) => $ccy.' '.number_format($row['total'], 2))->join(' · ')]],
            default => [['Issued invoices', $invoiceTotals->map(fn ($row) => $row->currency.' '.number_format($row->amount, 2))->join(' · ') ?: '—'], ['Payments collected', $collectionTotals->map(fn ($row) => $row->currency.' '.number_format($row->amount, 2))->join(' · ') ?: '—'], ['Open receivables', collect($receivablesByCurrency)->map(fn ($row, $ccy) => $ccy.' '.number_format($row['total'], 2))->join(' · ')], ['Overdue invoices', $metrics['overdue_invoices']], ['Claims awaiting approval', $metrics['expenses_pending']]],
        };
        return view('finance.index',compact('org','section','sectionMeta','sectionSummary','invoices','payments','expenses','credits','taxCodes','budgets','recurring','limits','receivables','receivablesByCurrency','invoiceTotals','collectionTotals','metrics','revenue','currency'));
    }

    private function invoiceFor(Request $r,Organization $org,int $id){return DB::table('finance_invoices')->where('organization_id',$org->id)->where('id',$id)->first()?:abort(404);}
    private function refreshInvoiceStatus(int $invoiceId):void{$i=DB::table('finance_invoices')->where('id',$invoiceId)->first();if(!$i||!in_array($i->status,['issued','part_paid','paid','overdue'],true))return;$paid=(float)DB::table('finance_payment_allocations as a')->join('finance_payments as p','p.id','=','a.payment_id')->where('a.invoice_id',$invoiceId)->where('p.status','posted')->sum('a.amount');$credits=(float)DB::table('finance_credit_notes')->where('invoice_id',$invoiceId)->where('status','issued')->sum('total');$open=max(0,(float)$i->total-$paid-$credits);$status=$open<=0?'paid':($paid+$credits>0?'part_paid':($i->due_date<today()->toDateString()?'overdue':'issued'));DB::table('finance_invoices')->where('id',$invoiceId)->update(['status'=>$status,'updated_at'=>now()]);}

    public function invoiceStore(Request $request,FinanceService $finance){$this->enabled();abort_unless($this->canDo($request,'finance.invoices.manage'),403);$org=$this->org($request);$d=$request->validate(['customer_name'=>['required','string','max:180'],'customer_email'=>['nullable','email','max:180'],'currency'=>['required','regex:/^[A-Z]{3}$/'],'invoice_date'=>['required','date'],'due_date'=>['required','date','after_or_equal:invoice_date'],'notes'=>['nullable','string','max:5000'],'service_name'=>['nullable','string','max:160'],'department_name'=>['nullable','string','max:120'],'project_id'=>['nullable','integer'],'lines'=>['required','array','min:1','max:25'],'lines.*.description'=>['required','string','max:240'],'lines.*.quantity'=>['required','numeric','gt:0','max:1000000'],'lines.*.unit_price'=>['required','numeric','min:0','max:1000000000'],'lines.*.tax_code_id'=>['nullable','integer']]);if($d['project_id']??null)abort_unless(DB::table('projects')->where('organization_id',$org->id)->where('id',$d['project_id'])->exists(),422);$id=$finance->createInvoice($org->id,$request->user()->id,$d,$d['lines']);AdminAudit::record('finance.invoice.created','finance_invoices',$id,null,['status'=>'draft'],$org->id);return back()->with('success','Draft invoice '.$this->invoiceFor($request,$org,$id)->reference.' created.');}

    public function invoiceSubmit(Request $request,int $invoice){$this->enabled();abort_unless($this->canDo($request,'finance.invoices.manage'),403);$org=$this->org($request);$i=$this->invoiceFor($request,$org,$invoice);abort_unless(in_array($i->status,['draft','rejected'],true),422);abort_unless((float)$i->total>0,422,'An invoice must have a positive total.');$d=$request->validate(['request_note'=>['nullable','string','max:3000']]);DB::transaction(function()use($i,$request,$d){DB::table('finance_invoices')->where('id',$i->id)->update(['status'=>'pending_approval','updated_at'=>now()]);DB::table('finance_invoice_approvals')->insert(['invoice_id'=>$i->id,'requested_by'=>$request->user()->id,'status'=>'pending','request_note'=>$d['request_note']??null,'created_at'=>now(),'updated_at'=>now()]);});AdminAudit::record('finance.invoice.submitted','finance_invoices',$i->id,['status'=>$i->status],['status'=>'pending_approval'],$org->id);return back()->with('success','Invoice submitted for independent approval.');}

    public function invoiceDecide(Request $request,int $invoice){$this->enabled();abort_unless($this->canDo($request,'finance.approve'),403);$org=$this->org($request);$i=$this->invoiceFor($request,$org,$invoice);$approval=DB::table('finance_invoice_approvals')->where('invoice_id',$i->id)->where('status','pending')->latest('id')->first();abort_unless($approval&&$i->status==='pending_approval',422);abort_if((int)$approval->requested_by===(int)$request->user()->id||(int)$i->created_by===(int)$request->user()->id,403,'The requester cannot approve their own invoice.');$d=$request->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'decision_note'=>['nullable','string','max:3000']]);$limits=DB::table('finance_approval_limits')->where('organization_id',$org->id)->where('currency',$i->currency)->get();if($d['decision']==='approved'&&$limits->isNotEmpty()&&!$request->user()->isSuperAdmin()){$roleNames=$request->user()->roles->pluck('name');$limit=$limits->whereIn('role_name',$roleNames)->max('maximum_amount');abort_unless($limit!==null&&(float)$i->total<=(float)$limit,403,'Your configured finance approval limit is below this invoice total.');}DB::transaction(function()use($approval,$i,$request,$d){DB::table('finance_invoice_approvals')->where('id',$approval->id)->update(['status'=>$d['decision'],'decided_by'=>$request->user()->id,'decision_note'=>$d['decision_note']??null,'decided_at'=>now(),'updated_at'=>now()]);DB::table('finance_invoices')->where('id',$i->id)->update(['status'=>$d['decision']==='approved'?'approved':'rejected','approved_by'=>$d['decision']==='approved'?$request->user()->id:null,'approved_at'=>$d['decision']==='approved'?now():null,'updated_at'=>now()]);});AdminAudit::record('finance.invoice.'.$d['decision'],'finance_invoices',$i->id,['status'=>'pending_approval'],['status'=>$d['decision']],$org->id);return back()->with('success','Invoice approval decision recorded.');}

    public function invoiceIssue(Request $request,int $invoice){$this->enabled();abort_unless($this->canDo($request,'finance.invoices.manage'),403);$org=$this->org($request);$i=$this->invoiceFor($request,$org,$invoice);abort_unless($i->status==='approved',422,'Only approved invoices can be issued.');DB::table('finance_invoices')->where('id',$i->id)->update(['status'=>$i->due_date<today()->toDateString()?'overdue':'issued','issued_at'=>now(),'updated_at'=>now()]);AdminAudit::record('finance.invoice.issued','finance_invoices',$i->id,['status'=>'approved'],['status'=>'issued'],$org->id);return back()->with('success','Invoice issued.');}

    public function paymentStore(Request $request){$this->enabled();abort_unless($this->canDo($request,'finance.payments.manage'),403);$org=$this->org($request);$d=$request->validate(['invoice_id'=>['required','integer'],'paid_on'=>['required','date'],'amount'=>['required','numeric','gt:0','max:1000000000'],'method'=>['nullable','string','max:40'],'reference'=>['nullable','string','max:80'],'memo'=>['nullable','string','max:2000']]);$i=$this->invoiceFor($request,$org,$d['invoice_id']);abort_unless(in_array($i->status,['issued','part_paid','overdue'],true),422,'Choose an issued and unpaid invoice.');DB::transaction(function()use($d,$i,$org,$request){$locked=DB::table('finance_invoices')->where('id',$i->id)->lockForUpdate()->first();abort_unless($locked&&in_array($locked->status,['issued','part_paid','overdue'],true),422,'Choose an issued and unpaid invoice.');$paid=(float)DB::table('finance_payment_allocations')->where('invoice_id',$i->id)->sum('amount');$credits=(float)DB::table('finance_credit_notes')->where('invoice_id',$i->id)->where('status','issued')->sum('total');$open=(float)$locked->total-$paid-$credits;abort_if((float)$d['amount']>$open+0.005,422,'Payment exceeds the remaining invoice balance.');$paymentId=DB::table('finance_payments')->insertGetId(['organization_id'=>$org->id,'reference'=>$d['reference']??null,'customer_name'=>$locked->customer_name,'currency'=>$locked->currency,'paid_on'=>$d['paid_on'],'amount'=>$d['amount'],'method'=>$d['method']??null,'status'=>'posted','memo'=>$d['memo']??null,'recorded_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('finance_payment_allocations')->insert(['payment_id'=>$paymentId,'invoice_id'=>$i->id,'amount'=>$d['amount'],'created_at'=>now(),'updated_at'=>now()]);$this->refreshInvoiceStatus($i->id);AdminAudit::record('finance.payment.recorded','finance_payments',$paymentId,null,['amount'=>$d['amount'],'invoice_id'=>$i->id],$org->id);},5);return back()->with('success','Payment recorded and allocated.');}

    public function paymentReconcile(Request $request,int $payment){$this->enabled();abort_unless($this->canDo($request,'finance.payments.manage'),403);$org=$this->org($request);$p=DB::table('finance_payments')->where('organization_id',$org->id)->where('id',$payment)->first()?:abort(404);abort_unless($p->status==='posted',422,'Only posted payments can be reconciled.');abort_if($p->is_reconciled,422,'This payment has already been reconciled.');$d=$request->validate(['reconciliation_reference'=>['nullable','string','max:100']]);DB::table('finance_payments')->where('id',$payment)->update(['is_reconciled'=>true,'reconciled_at'=>now(),'reconciliation_reference'=>$d['reconciliation_reference']??null,'updated_at'=>now()]);AdminAudit::record('finance.payment.reconciled','finance_payments',$payment,['is_reconciled'=>false],['is_reconciled'=>true,'reference'=>$d['reconciliation_reference']??null],$org->id);return back()->with('success','Payment marked reconciled against the supplied statement or receipt.');}

    public function creditStore(Request $request){$this->enabled();abort_unless($this->canDo($request,'finance.credits.manage'),403);$org=$this->org($request);$d=$request->validate(['invoice_id'=>['required','integer'],'reason'=>['required','string','max:240'],'subtotal'=>['required','numeric','gt:0'],'tax_total'=>['required','numeric','min:0'],'total'=>['required','numeric','gt:0']]);$i=$this->invoiceFor($request,$org,$d['invoice_id']);abort_unless(in_array($i->status,['issued','part_paid','overdue'],true),422,'Credit notes can only be raised against an invoice with an open balance.');abort_unless(abs((float)$d['total']-(float)$d['subtotal']-(float)$d['tax_total'])<0.02,422,'Credit total must equal subtotal plus tax.');$paid=(float)DB::table('finance_payment_allocations as a')->join('finance_payments as p','p.id','=','a.payment_id')->where('a.invoice_id',$i->id)->where('p.status','posted')->sum('a.amount');$credited=(float)DB::table('finance_credit_notes')->where('invoice_id',$i->id)->whereIn('status',['pending_approval','issued'])->sum('total');abort_if((float)$d['total']>(float)$i->total-$paid-$credited,422,'Credit exceeds the invoice amount remaining after payments and other credits.');$id=DB::transaction(function()use($d,$i,$org,$request){$ref=app(NumberSequence::class)->next('credit_note');return DB::table('finance_credit_notes')->insertGetId(['organization_id'=>$org->id,'invoice_id'=>$i->id,'reference'=>$ref,'reason'=>$d['reason'],'subtotal'=>$d['subtotal'],'tax_total'=>$d['tax_total'],'total'=>$d['total'],'status'=>'pending_approval','created_by'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]);});AdminAudit::record('finance.credit_note.submitted','finance_credit_notes',$id,null,['invoice_id'=>$i->id,'total'=>$d['total']],$org->id);return back()->with('success','Credit note submitted for independent approval.');}

    public function creditDecide(Request $request,int $credit){$this->enabled();abort_unless($this->canDo($request,'finance.approve'),403);$org=$this->org($request);$c=DB::table('finance_credit_notes')->where('organization_id',$org->id)->where('id',$credit)->first()?:abort(404);abort_unless($c->status==='pending_approval',422);abort_if((int)$c->created_by===(int)$request->user()->id,403,'The requester cannot approve their own credit note.');$d=$request->validate(['decision'=>['required',Rule::in(['approved','rejected'])]]);DB::table('finance_credit_notes')->where('id',$credit)->update(['status'=>$d['decision']==='approved'?'issued':'rejected','approved_by'=>$d['decision']==='approved'?$request->user()->id:null,'approved_at'=>$d['decision']==='approved'?now():null,'issued_at'=>$d['decision']==='approved'?now():null,'updated_at'=>now()]);$this->refreshInvoiceStatus($c->invoice_id);AdminAudit::record('finance.credit_note.'.$d['decision'],'finance_credit_notes',$credit,['status'=>'pending_approval'],['status'=>$d['decision']],$org->id);return back()->with('success','Credit note decision recorded.');}

