    public function expenseDecide(Request $request,int $expense){$this->enabled();abort_unless($this->canDo($request,'finance.expenses.approve'),403);$org=$this->org($request);$e=DB::table('finance_expenses')->where('organization_id',$org->id)->where('id',$expense)->first()?:abort(404);abort_unless($e->status==='pending_approval',422);abort_if((int)$e->claimant_id===(int)$request->user()->id,403,'You cannot approve your own expense claim.');$d=$request->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'decision_note'=>['nullable','string','max:2000']]);DB::table('finance_expenses')->where('id',$expense)->update(['status'=>$d['decision'],'decided_by'=>$request->user()->id,'decided_at'=>now(),'notes'=>trim(($e->notes??'')."\n".($d['decision_note']??'')),'updated_at'=>now()]);AdminAudit::record('finance.expense.'.$d['decision'],'finance_expenses',$expense,['status'=>'pending_approval'],['status'=>$d['decision']],$org->id);return back()->with('success','Expense claim decision recorded.');}

