    public function export(Request $request){$this->enabled();abort_unless($this->canDo($request,'finance.export'),403);$org=$this->org($request);$rows=DB::table('finance_invoices')->where('organization_id',$org->id)->orderBy('invoice_date')->get();return response()->streamDownload(function()use($rows,$org){$out=fopen('php://output','w');fputcsv($out,['Organization','Invoice reference','Customer','Currency','Invoice date','Due date','Subtotal','Tax','Total','Paid','Credits','Outstanding','Status']);foreach($rows as $i){$paid=(float)DB::table('finance_payment_allocations as a')->join('finance_payments as p','p.id','=','a.payment_id')->where('a.invoice_id',$i->id)->where('p.status','posted')->sum('a.amount');$credit=(float)DB::table('finance_credit_notes')->where('invoice_id',$i->id)->where('status','issued')->sum('total');fputcsv($out,[$org->name,$i->reference,$i->customer_name,$i->currency,$i->invoice_date,$i->due_date,$i->subtotal,$i->tax_total,$i->total,$paid,$credit,max(0,(float)$i->total-$paid-$credit),$i->status]);}fclose($out);},'finance-invoices-'.$org->code.'-'.today()->toDateString().'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
